import sqlite3
con = sqlite3.connect(':memory:')
setup(con)
class _Recorder:
    def __init__(self, con):
        self.con, self.calls = con, []

    def execute(self, sql, params=()):
        self.calls.append((sql, params))
        return self.con.execute(sql, params)

    def executemany(self, sql, rows):
        rows = list(rows)
        self.calls.append((sql, rows))
        return self.con.executemany(sql, rows)

    def cursor(self, *args, **kwargs):
        rec, cur = self, self.con.cursor(*args, **kwargs)

        class _Cursor:
            def execute(self, sql, params=()):
                rec.calls.append((sql, params))
                cur.execute(sql, params)
                return self

            def executemany(self, sql, rows):
                rows = list(rows)
                rec.calls.append((sql, rows))
                cur.executemany(sql, rows)
                return self

            def __getattr__(self, name):
                return getattr(cur, name)

        return _Cursor()

    def __enter__(self):
        self.con.__enter__()
        return self

    def __exit__(self, *exc):
        return self.con.__exit__(*exc)

    def __getattr__(self, name):
        return getattr(self.con, name)

rec = _Recorder(con)
add_score(rec, 'Zed', 4)
assert rec.calls, 'add_score should run its INSERT through the connection it is given'
sql, params = rec.calls[-1]
assert 'Zed' not in sql, 'the name is part of the SQL text: pass it as a parameter with ?'
assert 'Zed' in repr(params), 'pass the name as a parameter with ?'
assert top(con, 1) == [('Zed', 4)]

